mapper.sql:
WHERE 1 = 1

    AND u.user_no = #{query.userNo}


    AND a.media_type = #{query.mediaType}


    AND a.status = #{query.accountStatus}



        AND (
            NOT EXISTS (
                SELECT 1 FROM provider_media_filing any_f
                WHERE any_f.media_account_id = a.id
            )
            OR EXISTS (
                SELECT 1 FROM provider_media_filing f
                WHERE f.media_account_id = a.id
                  AND f.status = 'NOT_SUBMITTED'
            )
        )


        AND EXISTS (
            SELECT 1
            FROM provider_media_filing f
            JOIN short_drama_connection c ON c.id = f.connection_id
            WHERE f.media_account_id = a.id

                AND c.provider_id = #{query.providerId}


                AND f.filing_method = #{query.filingMethod}


                AND f.status = #{query.filingStatus}

        )

mapper.select:
SELECT a.*


ORDER BY a.id DESC
LIMIT #{offset}, #{size}
